/// <summary>
/// Configuration for the localhost control server, resolved from environment
/// variables:
/// <list type="bullet">
/// <item><c>VR_CONTROL_DISABLE=1</c> turns the whole server off.</item>
/// <item><c>VR_CONTROL_PORT</c> overrides the default loopback port (8765);
///   an unparseable value falls back to the default.</item>
/// <item><c>VR_CONTROL_TOKEN</c>, when set, requires a matching
///   <c>X-VR-Token</c> request header (else 401).</item>
/// <item><c>VR_CONTROL_FAIL_ON_BIND_CONFLICT=1</c> makes a port-in-use
///   bind failure propagate as an exception instead of being swallowed;
///   also accepts <c>true</c>/<c>yes</c> (case-insensitive).</item>
/// </list>
/// </summary>
public sealed record ControlServerOptions(bool Enabled, int Port, string? Token, bool FailOnBindConflict = false, string? InstanceId = null)
{
    private const int DefaultPort = 8765;

    public static ControlServerOptions FromEnvironment(IEnvironmentAccessor env)
    {
        var disabled = env.GetEnvironmentVariable("VR_CONTROL_DISABLE") == "1";

        var port = DefaultPort;
        var portValue = env.GetEnvironmentVariable("VR_CONTROL_PORT");
        if (!string.IsNullOrWhiteSpace(portValue)
            && int.TryParse(portValue, out var parsed)
            && parsed is > 0 and <= 65535)
        {
            port = parsed;
        }

        var token = env.GetEnvironmentVariable("VR_CONTROL_TOKEN");
        if (string.IsNullOrEmpty(token))
        {
            token = null;
        }

        var failOnBindConflict = IsTruthy(env.GetEnvironmentVariable("VR_CONTROL_FAIL_ON_BIND_CONFLICT"));

        var instanceId = Guid.NewGuid().ToString("N") + "-" + Environment.ProcessId;

        return new ControlServerOptions(Enabled: !disabled, Port: port, Token: token,
            FailOnBindConflict: failOnBindConflict, InstanceId: instanceId);
    }

    private static bool IsTruthy(string? value) =>
        string.Equals(value, "1", StringComparison.OrdinalIgnoreCase)
        || string.Equals(value, "true", StringComparison.OrdinalIgnoreCase)
        || string.Equals(value, "yes", StringComparison.OrdinalIgnoreCase);
}

/// <summary>The actual port the server bound (useful when <see cref="ControlServerOptions.Port"/> is 0).</summary>
public int BoundPort => _boundPort;

/// <summary>True when the control server is listening (bound and running).</summary>
public bool IsAvailable => _app is not null;

