    /// <summary>
    /// When the port is pre-occupied and VR_CONTROL_PORT is explicitly set,
    /// the control server must throw (fail loud) so the app knows the control
    /// API could not start — it must not silently run headless as a zombie.
    /// </summary>
    [AvaloniaFact]
    public async Task BindConflict_WithExplicitPort_Throws()
    {
        // Occupy a port.
        using var occupier = new TcpListener(IPAddress.Loopback, 0);
        occupier.Start();
        var occupiedPort = ((IPEndPoint)occupier.LocalEndpoint).Port;

        var vm = new MainWindowViewModel(new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
        var window = new MainWindow { DataContext = vm };
        var api = new ControlApi(vm, window);

        var env = new DictionaryEnvironmentAccessor { ["VR_CONTROL_PORT"] = occupiedPort.ToString() };
        var options = ControlServerOptions.FromEnvironment(env);
        // FailOnBindConflict is not set in env, but we explicitly construct
        // with FailOnBindConflict=true to prove the throw path works.
        var failOptions = options with { FailOnBindConflict = true };

        var server = new ControlServer(api, failOptions);

        var ex = Assert.ThrowsAny<Exception>(() => server.Start());
        Assert.Contains(ex.Message, "port", StringComparison.OrdinalIgnoreCase);
        Assert.False(server.IsAvailable, "IsAvailable must be false after a bind conflict.");
    }

    /// <summary>
    /// When the port is pre-occupied but VR_CONTROL_PORT is NOT explicitly
    /// set (default port, casual GUI use), startup continues without throwing
    /// and IsAvailable is false — the banner path (view-model can observe it).
    /// </summary>
    [AvaloniaFact]
    public async Task BindConflict_WithoutExplicitPort_DoesNotThrow_AndIsAvailableIsFalse()
    {
        // Occupy the DEFAULT port.
        using var occupier = new TcpListener(IPAddress.Loopback, 8765);
        occupier.Start();

        var vm = new MainWindowViewModel(new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
        var window = new MainWindow { DataContext = vm };
        var api = new ControlApi(vm, window);

        // Default port, no FailOnBindConflict — must NOT throw.
        var options = new ControlServerOptions(Enabled: true, Port: 8765, Token: null);

        var server = new ControlServer(api, options);

        // Must not throw.
        var ex = Record.Exception(() => server.Start());
        Assert.Null(ex);

        Assert.False(server.IsAvailable,
            "IsAvailable must be false when the control server could not bind (banner path).");
    }
}

